// Base64-inlined so the font ships inside the JS bundle itself instead of
// as a separate file — Next's serverless file tracing didn't reliably pick
// up the .ttf files referenced via fs/path.join(__dirname, ...) across a
// Vercel monorepo build, causing an ENOENT in production. Regenerate from
// noto-sans-jp-{400,700}.ttf if the kanji dataset grows and needs more
// glyph coverage (see scripts/build-kanji-data.mjs for the data/stroke
// pipeline; these font subsets are fetched separately via Google Fonts'
// `text=` subsetting parameter for just the glyphs actually used).

export const NOTO_SANS_JP_400 = "data:font/ttf;base64,";
export const NOTO_SANS_JP_700 = "data:font/ttf;base64,";
